}

import { ChangeDetectionStrategy, Component, signal } from '@angular/core';
import { NeuButtonComponent } from '@neural-ui/core/button';
import { NeuDialogComponent } from '@neural-ui/core/modal';

@Component({
  selector: 'example-overlays',
  standalone: true,
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [NeuButtonComponent, NeuDialogComponent],
  template: `
    <section aria-labelledby="overlay-heading">
      <h2 id="overlay-heading">Dialog ownership</h2>
      <label><input type="checkbox" [checked]="acceptClose()" (change)="acceptClose.set(!acceptClose())" /> Accept close requests</label>
      <button neu-button type="button" (neuClick)="open.set(true)">Edit customer</button>
      <neu-dialog [open]="open()" title="Edit customer" (closeRequested)="requestClose()"
        (opened)="opened.update(increment)" (closed)="closed.update(increment)">
        <p>Changes belong to the application.</p>
        <button neu-button type="button" (neuClick)="open.set(false)">Finish editing</button>
      </neu-dialog>
      <output data-testid="dialog-state">{{ open() }} / {{ requests() }} / {{ opened() }} / {{ closed() }}</output>
    </section>
  `,
})
export class OverlaysExample {
  readonly open = signal(false);
  readonly acceptClose = signal(true);
  readonly requests = signal(0);
  readonly opened = signal(0);
  readonly closed = signal(0);
  readonly increment = (value: number) => value + 1;
  requestClose(): void {
    this.requests.update(this.increment);
    if (this.acceptClose()) this.open.set(false);
  }
}

import { ChangeDetectionStrategy, Component, signal } from '@angular/core';
import { NeuTableComponent, type NeuTableColumn, type NeuTableQuery, type NeuTableSelection, type NeuTableSelectionOptions } from '@neural-ui/core/table';

interface Customer { id: number; name: string; }
type Field = 'name';

@Component({
  selector: 'example-table',
  standalone: true,
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [NeuTableComponent],
  template: `
    <section aria-labelledby="table-heading">
      <h2 id="table-heading">Customers</h2>
      <neu-table [data]="customers" [columns]="columns" [rowKey]="rowKey"
        [query]="query()" (queryChange)="query.set($event)"
        [selection]="selection()" (selectionChange)="selection.set($event.next)"
        [selectionOptions]="selectionOptions" />
      <output data-testid="table-sort">{{ query().sort[0]?.direction ?? 'none' }}</output>
      <output data-testid="table-selected">{{ selectedKeys() }}</output>
    </section>
  `,
})
export class TableExample {
  readonly customers: readonly Customer[] = [{ id: 1, name: 'Zoe' }, { id: 2, name: 'Ana' }, { id: 3, name: 'Leo' }];
  readonly rowKey = (row: Customer) => row.id;
  readonly columns: readonly NeuTableColumn<Customer, Field>[] = [
    { id: 'name', header: 'Customer', field: 'name', sort: { field: 'name' } },
  ];
  readonly query = signal<NeuTableQuery<Field>>({ page: 0, pageSize: 10, search: '', sort: [], filters: null });
  readonly selection = signal<NeuTableSelection<number, Field>>({ kind: 'keys', keys: [] });
  readonly selectionOptions: NeuTableSelectionOptions<Customer> = {
    mode: 'single', indicator: 'radio', selectOnRowClick: true, allowClear: true,
  };
  selectedKeys(): string {
    const value = this.selection();
    return value.kind === 'keys' ? value.keys.join(',') : 'all-matching';
  }
}

import { DOCUMENT } from '@angular/common';
import { ChangeDetectionStrategy, Component, inject, signal } from '@angular/core';
import { defineNeuPreset } from '@neural-ui/core';
import { NeuButtonComponent } from '@neural-ui/core/button';

export const neuralAiPreset = defineNeuPreset({
  name: 'neural-ai',
  light: { '--neu-primary': '#166534', '--neu-bg': '#f0fdf4', '--neu-text': '#142d20' },
  dark: { '--neu-primary': '#86efac', '--neu-bg': '#081a10', '--neu-text': '#f0fdf4' },
});

@Component({
  selector: 'example-theme',
  standalone: true,
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [NeuButtonComponent],
  template: `<button neu-button type="button" (neuClick)="toggle()">Toggle theme</button><output data-testid="theme-mode">{{ mode() }}</output>`,
})
export class ThemeExample {
  private readonly document = inject(DOCUMENT);
  readonly mode = signal<'light' | 'dark'>('light');
  toggle(): void {
    this.mode.update(value => value === 'light' ? 'dark' : 'light');
    this.document.documentElement.setAttribute('data-theme', this.mode());
  }
}
